%[text] %[text:anchor:H_798d] ## Using the PDE Toolbox: Additional Dimensions
%[text] The Partial Differential Equation Toolbox$^{\\trademark}${"altText":"^(trademark)"} solves systems of equations of the form
%[text]{"align":"center"} $\\mathbf{m}\\frac{\\partial^2\\mathbf{u}}{\\partial t^2} + \\mathbf{d}\\frac{\\partial \\mathbf{u}}{\\partial t} - \\nabla\\cdot (\\mathbf{c} \\otimes \\nabla \\mathbf{u}) + \\mathbf{a}\\mathbf{u} = \\mathbf{f}${"altText":"m(∂^2u)\/(∂ t^2) + d(∂ u)\/(∂ t) - ∇ · (c tensor product ∇ u) + au = f"}
%[text] where $\\textbf{m}${"altText":"m"}, $\\textbf{d}${"altText":"d"}, $\\textbf{a}${"altText":"a"}, and $\\textbf{f}${"altText":"f"} are $N${"altText":"N"}-by-$N${"altText":"N"} matrices for $N${"altText":"N"} equations, and $\\textbf{c}${"altText":"c"} is a square tensor of twice the spatial dimensions. Recall that our formulation was:
%[text]{"align":"center"} $\\frac{\\partial A}{\\partial t} = D\_A \\nabla^2A - AB^2 + f(1-A)${"altText":"(∂ A)\/(∂ t) = D\_A ∇^2A - AB^2 + f(1-A)"}
%[text]{"align":"center"} $\\frac{\\partial B}{\\partial t} = D\_B \\nabla^2B + AB^2+f(k+B)${"altText":"(∂ B)\/(∂ t) = D\_B ∇^2B + AB^2+f(k+B)"}
%[text] In this case, we have a system of equations where 
%[text]{"align":"center"} $\\textbf{u} = \\left\[\\matrix{A \\cr B}\\right\]${"altText":"u = \[matrix rows: A ; B\]"},     $\\textbf{m} = \\left\[\\matrix{0\\cr0}\\right\]${"altText":"m = \[0;0\]"},     $\\textbf{d} = \\left\[\\matrix{1\\cr1}\\right\]${"altText":"d = \[1;1\]"},     $\\textbf{c} = \\left\[\\matrix{D\_a\\cr D\_b}\\right\]${"altText":"c = \[D\_a; D\_b\]"},     $\\textbf{a} = \\left\[\\matrix{f\\cr -f}\\right\]${"altText":"a = \[f; -f\]"},     and     $\\textbf{f} = \\left\[\\matrix{-AB^2+f\\cr AB^2+fk}\\right\]${"altText":"f = \[-AB^2+f; AB^2+fk\]"}.
% Set up the geometry %[text:anchor:M_4907]
model = createpde(2);

% Start with a solid cube
gmCube = multicuboid(1,1,1);
% Cut a void out of the center
gmHole = multicuboid(0.4,0.4,0.9); %[control:dropdown:7b04]{"position":[22,25]} %[control:dropdown:8585]{"position":[26,29]}
gmHole = translate(gmHole,[0,0,0.05]);
gm = addVoid(gmCube,gmHole);
pdegplot(gm,"FaceAlpha",0.4)
model.Geometry = gm;
msh = generateMesh(model,GeometricOrder="linear");
pdemesh(msh,FaceAlpha=0.3)
%%
%[text] After setting up the geometry, you can define the parameters of the PDEs:
% Parameters of the PDEs %[text:anchor:M_2c14]
da = 1;
db = 0.5;
f = 0.026; %[control:dropdown:53b3]{"position":[5,10]}
k = 0.053; %[control:dropdown:466f]{"position":[5,10]}

% Define the vectors needed to represent the system
dVec = [1;1];
cVec = [da;db];
aVec = [f;-f];
fVec = @(region,state) [f-state.u(1,:).*state.u(2,:).^2;...
    state.u(1,:).*state.u(2,:).^2 + f*k];

% Set the coefficients in the PDE object model
specifyCoefficients(model,"m",0,"d",dVec,"c",cVec,"a",aVec,"f",fVec);
%[text] And the values of the initial conditions:
% Specify initial conditions %[text:anchor:M_4103]
icFcn = @(region) [sin(2*pi*region.x).*cos(2*pi*region.z);...
cos(6*pi*region.y).*sin(6*pi*region.x)];
setInitialConditions(model,icFcn);

% Set up the time vector
tlist = linspace(0,0.05,50);

% Compute the results
results = solvepde(model,tlist);
disp("Results computed.")
%[text] Visualize the results of the computation.
% Extract the results for B, starting with the initial values
nodalData = results.NodalSolution(:,2,1);

% Create PDE result visualization
resultViz = pdeviz(msh,nodalData, ...
    "AxesVisible",false, ...
    "MeshVisible",true, ...
    "ColorLimits",[0 1], ...
    "Transparency",0.4,...
    "Title","Initial Conditions");

% Animate the results for B
for ii2 = 1:(length(tlist)+10)
    if ii2<=10
        % Show the initial conditions for 10 frames in the animation
        resultViz.NodalData = nodalData;
    else 
        % Show the evolution of B over time
        resultViz.NodalData = results.NodalSolution(:,2,ii2-10);
        % rescale the colorbar for visibility into the variation
        resultViz.ColorLimits = [0 min([1,max(resultViz.NodalData)+0.01])];
        resultViz.Title = "Evolving";
    end
    pause(0.1)
end
