%[text] %[text:anchor:H_6241] ## Local Helper Functions
function out = FivePointLaplacian(in)
%[text] $\\frac{\\partial^2 B\_{i,j}}{\\partial x^2}+ \\frac{\\partial^2 B\_{i,j}}{\\partial y^2} \\approx -B\_{i,j} + \\frac{(B\_{i+1,j}+B\_{i-1,j} + B\_{i,j+1}+B\_{i,j-1})}{4}${"altText":"(∂^2 B\_(i,j))\/(∂ x^2)+ (∂^2 B\_(i,j))\/(∂ y^2) ≈ -B\_(i,j) + ((B\_(i+1,j)+B\_(i-1,j) + B\_(i,j+1)+B\_(i,j-1)))\/(4)"}
%[text] Periodic boundary conditions
out = -4*in ...
    + (circshift(in,[ 1, 0]) + circshift(in,[-1, 0])  ...
    +  circshift(in,[ 0, 1]) + circshift(in,[ 0,-1]));
end
%[text] [⇦ Return to text](internal:M_65f6)
function out = NinePointLaplacian(in) %[text:anchor:M_5dd8]
%[text] $\\frac{\\partial^2 B\_{i,j}}{\\partial x^2}+ \\frac{\\partial^2 B\_{i,j}}{\\partial y^2} \\approx -B\_{i,j} + \\frac{1}{5}(B\_{i+1,j}+B\_{i-1,j} + B\_{i,j+1}+B\_{i,j-1}) + \\frac{1}{20}\\left(B\_{i+1,j+1}+B\_{i-1,j+1}+B\_{i-1,j-1}+B\_{i+1,j-1}\\right)${"altText":"(∂^2 B\_(i,j))\/(∂ x^2)+ (∂^2 B\_(i,j))\/(∂ y^2) ≈ -B\_(i,j) + (1)\/(5)(B\_(i+1,j)+B\_(i-1,j) + B\_(i,j+1)+B\_(i,j-1)) + (1)\/(20)(B\_(i+1,j+1)+B\_(i-1,j+1)+B\_(i-1,j-1)+B\_(i+1,j-1))"}
%[text] Periodic boundary conditions
out = -in ...
    + 0.20*(circshift(in,[ 1, 0]) + circshift(in,[-1, 0])  ...
    +       circshift(in,[ 0, 1]) + circshift(in,[ 0,-1])) ...
    + 0.05*(circshift(in,[ 1, 1]) + circshift(in,[-1, 1])  ...
    +       circshift(in,[-1,-1]) + circshift(in,[ 1,-1]));
end
%[text] [⇦ Return to text](internal:M_15b7)
function [t, A, B] = initial_conditions(n,opts)
arguments
    n 
    opts.InitVals {mustBeMember(opts.InitVals,1:3)} = 1
end
t = 0;
% Initialize A to one
A = ones(n);
B = zeros(n);

if opts.InitVals == 1
    % Initialize B with several clumps of ones
    idx1 = n/2-29;
    idx2 = n/2-20;
    idx3 = n/2-10;
    idx4 = n/2+10;
    idx5 = n/2+20;
    B(idx1:idx2,idx1:idx3) = 1;
    B((idx2+1):n/2,(idx3+1):n/2)=1;
    B(idx4:idx5,idx4:idx5) = 1;
elseif opts.InitVals == 2
    % Initialize B with a border of ones
    B(:,1:3) = 1;
    B(:,end-2:end) = 1;
    B(1:3,:) = 1;
    B(end-2:end,:) = 1;
elseif opts.InitVals == 3
    % Initialize B with a greyscale image
    load("Mouse.mat","mouse")
    if n<192
        B = 1-mouse((n-192)/2+1:(n-192)/2+n,((500-n)+1):500);
    elseif n<500
        B(((n-192)/2+1):(n+192)/2,:) = 1-mouse(:,((500-n)+1):500);
    else
        B(((n-192)/2+1):(n+192)/2,1:500) = 1-mouse;
    end
end
end
%[text] **Hint:** Notes on choices of initial conditions.
% f = 0.055 and k = 0.062 generates a brain-coral type pattern
% f = 0.054 and k = 0.061 generates a maze-type pattern
% f = 0.026 and k = 0.062 generates spots
% f = 0.037 and k = 0.062 generates spots and lines
% f = 0.013 and k = 0.053 is pretty (moving dots) or k=0.051 (moving squiggles)
% f = 0.013 and k = 0.049 moving spirals, but k=0.047 dies out
% f = 0.017 and k = 0.049 concentric circles with original ICs
% f = 0.017 and k = 0.042 elaborate flashing patterns
% f = 0.017 and k = 0.044 stripey flashing patterns
% f = 0.018 and k = 0.051 particularly kaleidoscopic with border ICs

%[appendix]{"version":"1.0"}
%---
%[metadata:view]
%   data: {"layout":"inline","rightPanelPercent":40}
%---
%[text:image:8875]
%   data: {"align":"middle","height":24,"src":"data:image\/png;base64,iVBORw0KGgoAAAANSUhEUgAAABgAAAAYCAYAAADgdz34AAAAjElEQVR42mP4\/\/8\/AwgnJiYapKamfgfS\/ynBUDMMYOYywBggiYcPH\/6nFIDMAJmFYQHIdmoBqFm4LZjrYPd\/gpoyGIPYVLeA5j6gmwUlJaVAxUlgDGKPBhFODaQG1QgIoqKtr\/6r99wlCYP0EG0BSMOWe\/9JwiA9oxaMWkBHC2ieD2iSk+lR6dOk2QIAjF+EgB\/BqfoAAAAASUVORK5CYII=","width":24}
